+/**
+ * Replaces the composite meter registry with one that returns its members in a deterministic order,
+ * with the OpenTelemetry registry last.
+ *
+ * <p>{@link CompositeMeterRegistry} keeps its members in an identity hash set, so the iteration
+ * order of {@link CompositeMeterRegistry#getRegistries()} is arbitrary and can differ between JVM
+ * runs. Spring Boot's metrics endpoint reads meter values from the first registry that has a
+ * matching meter, which makes reading metrics through the actuator endpoint unreliable when the
+ * OpenTelemetry registry, which does not support reading metric values, is part of the composite.
+ */
+class CompositeMeterRegistryPostProcessor implements BeanPostProcessor {
+
+  @Override
+  public Object postProcessAfterInitialization(Object bean, String beanName) {
+    if (!(bean instanceof CompositeMeterRegistry)
+        || !beanName.equals("compositeMeterRegistry")
+        || !bean.getClass().getSimpleName().equals("AutoConfiguredCompositeMeterRegistry")) {
+      return bean;
+    }
+    CompositeMeterRegistry original = (CompositeMeterRegistry) bean;
+    if (original.getRegistries().stream().noneMatch(OpenTelemetryMeterRegistry.class::isInstance)) {
+      return bean;
